+    let mut parser = JsonParser::new("\"a\\nb\\tc\"");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::String(s) if s == "a\nb\tc"));
+}
+
+#[test]
+fn test_parse_invalid_json() {
+    let mut parser = JsonParser::new("{\"a\": }");
+    assert!(parser.parse().is_err());
