+export function loadConfig(path: string): ConfigFile {
+  const content = require('fs').readFileSync(path, 'utf-8');
+  if (path.endsWith('.json')) {
+    return JSON.parse(content);
+  }
+  // 简化版 YAML 解析
+  const result: ConfigFile = {};
+  for (const line of content.split('\n')) {
