+export function mergeConfig(
+  args: ParsedArgs,
+  config: ConfigFile,
+  options: Option[]
+): ParsedArgs {
+  const result = { ...args };
+  for (const opt of options) {
+    const configValue = config[opt.name];
+    if (
+      configValue !== undefined &&
+      !(opt.name + '_from' in result)
+    ) {
+      result[opt.name] = configValue as string | boolean;
+      result[opt.name + '_from'] = 'config';
+    }
+  }
